#include <vector>
#include <algorithm>

class Solution {
public:
    int minTimeToTransport(std::vector<int>& positions, std::vector<int>& speeds, int k) {
        int n = positions.size();
        std::vector<int> times(n);
        for (int i = 0; i < n; ++i) {
            times[i] = (positions[i] + speeds[i] - 1) / speeds[i];
        }
        std::sort(times.begin(), times.end());

        int ans = 0;
        for (int i = k - 1; i < n; i += k) {
            ans = std::max(ans, times[i]);
        }
        if (n % k != 0) {
            ans = std::max(ans, times.back());
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minTimeToTransport(int[] positions, int[] speeds, int k) {
        int n = positions.length;
        int[] times = new int[n];
        for (int i = 0; i < n; i++) {
            times[i] = (positions[i] + speeds[i] - 1) / speeds[i];
        }
        Arrays.sort(times);

        int ans = 0;
        for (int i = k - 1; i < n; i += k) {
            ans = Math.max(ans, times[i]);
        }
        if (n % k != 0) {
            ans = Math.max(ans, times[n - 1]);
        }
        return ans;
    }
}

/**
 * @param {number[]} positions
 * @param {number[]} speeds
 * @param {number} k
 * @return {number}
 */
var minTimeToTransport = function(positions, speeds, k) {
    const n = positions.length;
    const times = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        times[i] = Math.ceil(positions[i] / speeds[i]);
    }
    times.sort();

    let ans = 0;
    for (let i = k - 1; i < n; i += k) {
        if (times[i] > ans) ans = times[i];
    }
    if (n % k !== 0) {
        if (times[n - 1] > ans) ans = times[n - 1];
    }
    return ans;
};
